import React, { useState } from 'react';

const UploadForm = ({ contract, account }) => {
  const [file, setFile] = useState(null);
  const [description, setDescription] = useState('');
  const [uploading, setUploading] = useState(false);
  const [hash, setHash] = useState('');
  const [uploadSuccess, setUploadSuccess] = useState(false);

  const handleFileChange = (e) => {
    if (e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!file || !description) return;

    try {
      setUploading(true);
      // Simulate IPFS upload by generating a random hash
      // In a real app, you would upload to IPFS here
      const mockHash = `ipfs-${Math.random().toString(36).substring(2, 15)}`;
      setHash(mockHash);

      // Create a simple JSON record
      const record = JSON.stringify({
        description,
        filename: file.name,
        type: file.type,
        size: file.size,
        dateAdded: new Date().toISOString(),
        hash: mockHash
      });

      // Add record to blockchain
      await contract.addRecord(record);
      setUploadSuccess(true);
      setDescription('');
      setFile(null);
    } catch (error) {
      console.error("Error uploading record:", error);
      alert("Failed to upload record. See console for details.");
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="upload-form">
      <h3>Upload Medical Record</h3>
      
      {uploadSuccess ? (
        <div className="success-message">
          <p>Record successfully uploaded to the blockchain!</p>
          <p>IPFS Hash: {hash}</p>
          <button onClick={() => setUploadSuccess(false)}>Upload Another</button>
        </div>
      ) : (
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>File:</label>
            <input 
              type="file" 
              onChange={handleFileChange} 
              required 
            />
          </div>
          
          <div className="form-group">
            <label>Description:</label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Enter record description"
              required
            />
          </div>
          
          <button type="submit" disabled={uploading || !file || !description}>
            {uploading ? 'Uploading...' : 'Upload Record'}
          </button>
        </form>
      )}
    </div>
  );
};

export default UploadForm;
